    async function salvarURL() { 
        const inputUrl = document.getElementById('configUrlApp').value.trim(); if(!inputUrl) return alert("Digite a URL primeiro!"); 
        document.getElementById('loadingOverlay').style.display = 'flex'; document.getElementById('loadingText').innerHTML = "Conectando à nuvem e puxando dados...<br><span style='font-size: 14px; font-weight: normal; margin-top: 10px; display: block;'>Por favor, aguarde e não feche.</span>";
        try { let fetchUrl = inputUrl + (inputUrl.includes('?') ? '&' : '?') + 'nocache=' + Date.now(); let res = await fetch(fetchUrl, { redirect: "follow", cache: "no-store" }); let nuvemDB = await res.json();
            if(nuvemDB && nuvemDB.app_id === "alofeira") { nuvemDB = normalizarBanco(nuvemDB); nuvemDB.configs.url = inputUrl; nuvemDB.configs.dadosBaixados = true; if(nuvemDB.configs.ultimaMudancaLocal === undefined) nuvemDB.configs.ultimaMudancaLocal = 0; db = nuvemDB; salvarBanco(); alert("✅ Conexão estabelecida! Todos os dados foram puxados da nuvem com sucesso."); location.reload(); } else { alert("❌ O link parece correto, mas não encontrei o banco de dados lá. Verifique a URL."); }
        } catch(e) { alert("❌ Falha na conexão. Verifique sua internet ou se a URL está correta e tente de novo."); } finally { document.getElementById('loadingOverlay').style.display = 'none'; }
    }
    
    function isUsuarioGerenciando() { return Array.from(document.querySelectorAll('.modal-overlay')).some(el => el.style.display === 'flex'); }
    
    async function sincronizarFundo(forcado = false, apenasEmpurrar = false) {
        if(!db.configs.url) return; if(isUsuarioGerenciando() && !forcado && !apenasEmpurrar) return; if(isSyncingFundo) { if(forcado) alert("🔄 O sistema já está processando dados com a nuvem no momento. Aguarde alguns segundos."); return; } if(document.hidden && !forcado && !apenasEmpurrar) return;
        let temRascunho = db.pedidosAtivos.some(pa => pa.status === 'rascunho' && !pa.excluido); if(temRascunho && db.configs.modo === 'pedido' && !forcado && !apenasEmpurrar) return;
        isSyncingFundo = true; let indicador = document.getElementById('syncIndicador'); indicador.style.opacity = '1';
        try {
            let precisaAtualizarNuvem = false;
            if (!apenasEmpurrar) {
                let fetchUrl = db.configs.url + (db.configs.url.includes('?') ? '&' : '?') + 'nocache=' + Date.now(); let res = await fetch(fetchUrl, { redirect: "follow", cache: "no-store" }); let nuvemDB = await res.json(); 
                if(nuvemDB && nuvemDB.app_id === "alofeira" && nuvemDB.pedidosAtivos) { nuvemDB = normalizarBanco(nuvemDB);
                    let jsonAntes = JSON.stringify(db.pedidosAtivos); let mergedPedidos = new Map();
                    nuvemDB.pedidosAtivos.forEach(pCloud => { if(pCloud.status !== 'rascunho') { mergedPedidos.set(pCloud.idUnico, pCloud); } });
                    let pedidosLocais = db.pedidosAtivos || [];
                    pedidosLocais.forEach(pLoc => { if(pLoc.status === 'rascunho') { mergedPedidos.set(pLoc.idUnico, pLoc); return; } let pCloud = mergedPedidos.get(pLoc.idUnico); let tLoc = pLoc.dataStatus || 0; let tCloud = pCloud ? (pCloud.dataStatus || 0) : 0; if(!pCloud || tLoc > tCloud) { mergedPedidos.set(pLoc.idUnico, pLoc); precisaAtualizarNuvem = true; } });
                    db.pedidosAtivos = Array.from(mergedPedidos.values());
                    let localMod = db.configs.ultimaMudancaLocal || 0; let cloudMod = (nuvemDB.configs && nuvemDB.configs.ultimaMudancaLocal) ? nuvemDB.configs.ultimaMudancaLocal : 0;
                    if (cloudMod >= localMod || localMod === 0) { if(nuvemDB.produtos) db.produtos = nuvemDB.produtos; if(nuvemDB.categorias) db.categorias = nuvemDB.categorias; if(nuvemDB.fornecedores) db.fornecedores = nuvemDB.fornecedores; if(nuvemDB.colaboradores) db.colaboradores = nuvemDB.colaboradores; if(nuvemDB.restaurante) db.restaurante = nuvemDB.restaurante; if(nuvemDB.configs) { if(nuvemDB.configs.exigirColaborador !== undefined) db.configs.exigirColaborador = nuvemDB.configs.exigirColaborador; if(nuvemDB.configs.senhaAdmin) db.configs.senhaAdmin = nuvemDB.configs.senhaAdmin; db.configs.ultimaMudancaLocal = cloudMod; } } else if (localMod > cloudMod) { precisaAtualizarNuvem = true; }
                    db.configs.dadosBaixados = true; salvarBanco();
                    if (db.configs.exigirColaborador && !db.configs.colabAtivoId && document.getElementById('modalColaboradorObrigatorio').style.display !== 'flex') { fecharModal('modalConfigAvancadas'); fecharModal('modalPainelUnificado'); abrirSelecaoColaboradorInicial(false); }
                    let jsonDepois = JSON.stringify(db.pedidosAtivos); if(jsonAntes !== jsonDepois && !isUsuarioGerenciando()) { renderizarLista(); }
                }
            }
            if (precisaAtualizarNuvem || apenasEmpurrar || forcado) {
                let dbParaNuvem = JSON.parse(JSON.stringify(db)); dbParaNuvem.pedidosAtivos = dbParaNuvem.pedidosAtivos.filter(p => p.status !== 'rascunho');
                let response = await fetch(db.configs.url, { method: 'POST', redirect: "follow", headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify({ action: 'salvar_banco', dados: dbParaNuvem }) }); if(response.ok) { salvarBanco(); }
            }
        } catch(e) { console.error("Erro na sincronização de fundo", e); } finally { isSyncingFundo = false; indicador.style.opacity = '0'; }
    }
