    function exportarDados() { db.app_id = "alofeira"; const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(db)); const downloadAnchorNode = document.createElement('a'); downloadAnchorNode.setAttribute("href", dataStr); downloadAnchorNode.setAttribute("download", "alofeira_bkp_" + getHojeSTR() + ".json"); document.body.appendChild(downloadAnchorNode); downloadAnchorNode.click(); downloadAnchorNode.remove(); }
    
    function importarDados(event) { const file = event.target.files[0]; if(!file) return; const reader = new FileReader(); reader.onload = function(e) { try { const importedDb = JSON.parse(e.target.result); if(importedDb && importedDb.app_id === "alofeira") { let urlSalva = db.configs.url; db = importedDb; if (urlSalva) db.configs.url = urlSalva; if(!db.configs) db.configs = {}; db.configs.ultimaMudancaLocal = Date.now(); salvarBanco(); alert("✅ Arquivo carregado no celular!\n\nAgora, vá na Engrenagem -> Avançado e clique no botão 'Forçar Envio Completo pra Nuvem' para salvar lá."); location.reload(); } else { alert("Arquivo de backup inválido."); } } catch(err) { alert("Erro ao ler o arquivo."); } }; reader.readAsText(file); event.target.value = ''; }
    
