    function filtrarCat(catId) { if (catId === null && categoriaAtual === null && db.configs.modo === 'compras') { agrupamentoCompradoAtivo = !agrupamentoCompradoAtivo; } else { agrupamentoCompradoAtivo = false; categoriaAtual = catId; } renderizarFiltros(); renderizarLista(); }
    
    function limparComprasAntigas() {
        let concluidos = db.pedidosAtivos.filter(pa => !pa.excluido && !pa.ocultoCompras && (pa.status === 'comprado' || pa.status === 'entregue'));
        if(concluidos.length === 0) return alert("Não há itens comprados ou entregues na tela para limpar.");
        if(!confirm(`Deseja limpar visualmente ${concluidos.length} item(ns) concluído(s) da lista? (Eles continuarão registrados no histórico)`)) return;
        let backupEstados = [];
        concluidos.forEach(pa => {
            backupEstados.push(JSON.parse(JSON.stringify(pa)));
            pa.ocultoCompras = true;
        });
        pilhaDesfazer.push(backupEstados);
        atualizarBotaoDesfazer();
        salvarBanco();
        renderizarLista();
        sincronizarFundo(false, true);
    }

    function toggleModoSelecao() { modoSelecaoAtivo = !modoSelecaoAtivo; document.getElementById('btnModoSelecaoBar').style.backgroundColor = modoSelecaoAtivo ? (db.configs.modo === 'pedido' ? '#1565C0' : '#6a1b9a') : 'rgba(255,255,255,0.15)'; if (db.configs.modo === 'compras') { document.getElementById('btnMassaComprado').style.display = modoSelecaoAtivo ? 'flex' : 'none'; document.getElementById('btnMassaPedForn').style.display = modoSelecaoAtivo ? 'flex' : 'none'; document.getElementById('btnMassaVincular').style.display = modoSelecaoAtivo ? 'flex' : 'none'; } else { document.getElementById('btnMassaVincular').style.display = modoSelecaoAtivo ? 'flex' : 'none'; } if (modoSelecaoAtivo) { document.getElementById('btnDesfazerBar').style.display = 'none'; } else { atualizarBotaoDesfazer(); } if(!modoSelecaoAtivo) itensSelecionadosRelatorio.clear(); renderizarLista(); }
    function selecionarGrupoCompras(grupoId, tipo = 'cat') { if(!modoSelecaoAtivo) return; let seletor = tipo === 'cat' ? `.item[data-grp-cat="${grupoId}"]` : `.item[data-grp-sub="${grupoId}"]`; let itensNode = document.querySelectorAll(seletor); let allIds = Array.from(itensNode).map(el => el.getAttribute('data-id')); if(allIds.length === 0) return; let allSelected = allIds.every(id => itensSelecionadosRelatorio.has(id)); if(allSelected) { allIds.forEach(id => { itensSelecionadosRelatorio.delete(id); let el = document.querySelector(`.item[data-id="${id}"]`); if(el) el.classList.remove('selecionado'); }); } else { allIds.forEach(id => { itensSelecionadosRelatorio.add(id); let el = document.querySelector(`.item[data-id="${id}"]`); if(el) el.classList.add('selecionado'); }); } }
    function selecionarGrupoPedido(grupoId, tipo = 'cat') { if(!modoSelecaoAtivo) return; let seletor = tipo === 'cat' ? `.item[data-cat-id="${grupoId}"]` : `.item[data-sub-id="${grupoId}"]`; let itensNode = document.querySelectorAll(seletor); let allIds = Array.from(itensNode).map(el => el.getAttribute('data-id')); if(allIds.length === 0) return; let allSelected = allIds.every(id => itensSelecionadosRelatorio.has(id)); if(allSelected) { allIds.forEach(id => { itensSelecionadosRelatorio.delete(id); let el = document.querySelector(`.item[data-id="${id}"]`); if(el) el.classList.remove('selecionado'); }); } else { allIds.forEach(id => { itensSelecionadosRelatorio.add(id); let el = document.querySelector(`.item[data-id="${id}"]`); if(el) el.classList.add('selecionado'); }); } }
    
    function acaoEmMassa(novoStatus) { if(itensSelecionadosRelatorio.size === 0) return alert("Selecione os itens primeiro tocando neles."); let acaoNome = novoStatus === 'comprado' ? 'Comprado / Entregue' : 'Pedido ao Fornecedor'; if(!confirm(`Deseja alterar os itens selecionados para '${acaoNome}'?`)) return; let backupEstados = []; let alterouAlgo = false; let pularam = 0; let apenasReceber = getPermissaoColab(); let agora = Date.now(); itensSelecionadosRelatorio.forEach(idUnico => { let pa = db.pedidosAtivos.find(x => x.idUnico === idUnico); if (pa && !pa.excluido && pa.status !== 'cancelado') { if (apenasReceber && novoStatus === 'pedido_forn') { pularam++; return; } if (apenasReceber && novoStatus === 'comprado' && pa.status !== 'pedido_forn') { pularam++; return; } backupEstados.push(JSON.parse(JSON.stringify(pa))); pa.transicaoProgresso = agora; pa.statusAnterior = pa.status; pa.status = novoStatus; pa.dataStatus = agora; if (novoStatus === 'comprado') { pa.dataConclusao = agora; } else { delete pa.dataConclusao; } if (novoStatus === 'pedido_forn') { pa.dataPedidoFornecedor = agora; } alterouAlgo = true; } }); if (pularam > 0) alert(`${pularam} itens não foram alterados devido às restrições do seu perfil (Apenas Receber).`); if (alterouAlgo) { pilhaDesfazer.push(backupEstados); atualizarBotaoDesfazer(); salvarBanco(); toggleModoSelecao(); renderizarLista(); setTimeout(() => { renderizarLista(); }, 10000); sincronizarFundo(false, true); } }
    function abrirModalMassaVincular() { if(itensSelecionadosRelatorio.size === 0) return alert("Selecione itens primeiro."); const selForn = document.getElementById('massaVincularForn'); selForn.innerHTML = '<option value="">-- Escolha o Fornecedor --</option>'; let fornOrdem = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdem.forEach(f => selForn.innerHTML += `<option value="${f.id}">${f.nome}</option>`); document.getElementById('modalMassaVincular').style.display = 'flex'; }
    function confirmarMassaVincular() { const fornId = document.getElementById('massaVincularForn').value; if(!fornId) return alert("Selecione um fornecedor."); itensSelecionadosRelatorio.forEach(idSelecionado => { let p; if (db.configs.modo === 'compras') { let pa = db.pedidosAtivos.find(x => x.idUnico === idSelecionado); if (pa) p = db.produtos.find(prod => prod.id === pa.produtoId); } else { p = db.produtos.find(prod => prod.id === idSelecionado); } if (p) { if (!p.fornecedores) p.fornecedores = []; if (!p.fornecedores.includes(fornId)) { p.fornecedores.push(fornId); } } }); salvarBanco(); fecharModal('modalMassaVincular'); toggleModoSelecao(); renderizarLista(); sincronizarFundo(false, true); alert("Fornecedor vinculado aos itens selecionados!"); }
    function abrirModalFiltroFornCompras() { const selForn = document.getElementById('filtroComprasForn'); selForn.innerHTML = '<option value="">-- Mostrar Todos os Itens --</option>'; let fornOrdem = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdem.forEach(f => selForn.innerHTML += `<option value="${f.id}">${f.nome}</option>`); selForn.value = filtroFornecedorComprasId || ""; document.getElementById('modalFiltroFornCompras').style.display = 'flex'; }
    function aplicarFiltroFornCompras() { filtroFornecedorComprasId = document.getElementById('filtroComprasForn').value; fecharModal('modalFiltroFornCompras'); const btn = document.getElementById('btnFiltroForn'); if (filtroFornecedorComprasId) { btn.style.backgroundColor = db.configs.modo === 'pedido' ? '#1565C0' : '#6a1b9a'; } else { btn.style.backgroundColor = 'rgba(255,255,255,0.15)'; } renderizarLista(); }
