    function getPermissaoColab() { let c = db.colaboradores.find(col => col.id === db.configs.colabAtivoId); return c ? (c.apenasReceber || false) : false; }

    function acaoToqueSimples(el) { if(db.configs.modo === 'pedido') { const pId = el.getAttribute('data-id'); const pedId = el.getAttribute('data-pedid'); if(!pedId) { const p = db.produtos.find(x => x.id === pId); if(!p) return; let qtd = (p.qtdPadrao !== null && p.qtdPadrao !== '') ? p.qtdPadrao : ''; let un = p.unidades[0] || ''; let obsPad = p.obsPadrao || ''; let novoPedId = 'pa_' + Date.now(); db.pedidosAtivos.push({ idUnico: novoPedId, produtoId: pId, qtd: qtd, unidade: un, obs: obsPad, status: 'rascunho', dataStatus: Date.now(), excluido: false, historico: [], colaboradorId: db.configs.colabAtivoId }); salvarBanco(); renderizarLista(); } else { let badge = el.querySelector('.status-badge'); if(badge) { badge.classList.remove('shake'); void badge.offsetWidth; badge.classList.add('shake'); } } } }
    function acaoDuploToque(el) { if(db.configs.modo === 'pedido') { const pId = el.getAttribute('data-id'); const pedidosDeste = db.pedidosAtivos.filter(pa => pa.produtoId === pId && !pa.excluido && (pa.status === 'rascunho' || pa.status === 'pendente' || pa.status === 'pedido_forn')); const pedidoEditavel = pedidosDeste[pedidosDeste.length-1]; if(pedidoEditavel && pedidoEditavel.status !== 'rascunho') { let colabLogado = db.colaboradores.find(c => c.id === db.configs.colabAtivoId); let isAdmin = (!colabLogado || colabLogado.isAdmin); if(!isAdmin && pedidoEditavel.colaboradorId !== db.configs.colabAtivoId) { return alert("🔒 Acesso Negado: Você só pode visualizar e editar pedidos que foram enviados pelo seu próprio perfil."); } } abrirModalEditarPedido(pedidoEditavel ? pedidoEditavel.idUnico : null, pId); } else { if (getPermissaoColab()) return alert("Seu perfil não permite editar os detalhes das compras."); const paId = el.getAttribute('data-id'); const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa && !pa.excluido) { abrirHistoricoCompra(paId); } } }
    function acaoSegurar(el) { if(db.configs.modo === 'compras') { if(modoSelecaoAtivo) return; if (getPermissaoColab()) return; const paId = el.getAttribute('data-id'); const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa && !pa.excluido && pa.status === 'pendente') { let agora = Date.now(); registrarDesfazer(pa); pa.transicaoProgresso = agora; pa.statusAnterior = 'pendente'; pa.status = 'pedido_forn'; pa.dataStatus = agora; pa.dataPedidoFornecedor = agora; delete pa.dataConclusao; salvarBanco(); renderizarLista(); setTimeout(() => { renderizarLista(); }, 10000); sincronizarFundo(false, true); } } }
    function acaoDeslizarDireita(el) { if(db.configs.modo === 'compras') { const apenasReceber = getPermissaoColab(); const paId = el.getAttribute('data-id'); const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa) { if(pa.excluido) { if (apenasReceber) return alert("Seu perfil não permite alterar itens excluídos."); if(confirm("Desfazer exclusão do item e voltar à lista?")) { registrarDesfazer(pa); pa.excluido = false; pa.excluidoCompras = false; pa.status = 'pendente'; pa.dataStatus = pa.dataEnvio || parseInt(pa.idUnico.split('_')[1]); delete pa.dataPedidoFornecedor; salvarBanco(); renderizarLista(); sincronizarFundo(false, true); } } else if (pa.status === 'cancelado') { if (apenasReceber) return alert("Seu perfil não permite alterar itens cancelados."); registrarDesfazer(pa); pa.status = 'pendente'; pa.dataStatus = pa.dataEnvio || parseInt(pa.idUnico.split('_')[1]); delete pa.dataPedidoFornecedor; salvarBanco(); renderizarLista(); sincronizarFundo(false, true); } else { if (apenasReceber && pa.status !== 'pedido_forn') return alert("Seu perfil só permite dar recebido em itens marcados como 'Pedido ao Fornecedor'."); if (pa.status === 'pendente') { registrarDesfazer(pa); pa.transicaoProgresso = Date.now(); pa.statusAnterior = 'pendente'; pa.status = 'comprado'; pa.dataConclusao = Date.now(); pa.dataStatus = Date.now(); delete pa.dataPedidoFornecedor; salvarBanco(); renderizarLista(); setTimeout(() => { renderizarLista(); }, 10000); sincronizarFundo(false, true); } else if (pa.status === 'pedido_forn') { registrarDesfazer(pa); pa.transicaoProgresso = Date.now(); pa.statusAnterior = 'pedido_forn'; pa.status = 'entregue'; pa.dataConclusao = Date.now(); pa.dataStatus = Date.now(); salvarBanco(); renderizarLista(); setTimeout(() => { renderizarLista(); }, 10000); sincronizarFundo(false, true); } } } } }
    function abrirConfirmarCancelamento(paId) { const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(!pa) return; const p = db.produtos.find(prod => prod.id === pa.produtoId); document.getElementById('cancelamentoCompraId').value = paId; document.getElementById('textoConfirmarCancelamento').innerHTML = `Deseja cancelar <b>${p ? p.nome : 'este item'}</b>?<br><span style="font-size:12px; color:#666;">Ele ficará marcado como cancelado e poderá ser desfeito pelo botão de desfazer.</span>`; document.getElementById('modalConfirmarCancelamento').style.display = 'flex'; }
    function confirmarCancelamentoCompra() { const paId = document.getElementById('cancelamentoCompraId').value; const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(!pa) return fecharModal('modalConfirmarCancelamento'); registrarDesfazer(pa); delete pa.transicaoProgresso; delete pa.statusAnterior; pa.status = 'cancelado'; pa.dataStatus = Date.now(); delete pa.dataConclusao; delete pa.dataPedidoFornecedor; salvarBanco(); fecharModal('modalConfirmarCancelamento'); renderizarLista(); sincronizarFundo(false, true); }
    function acaoDeslizarEsquerda(el) { if(db.configs.modo === 'pedido') { const pedId = el.getAttribute('data-pedid'); if(pedId) { let pa = db.pedidosAtivos.find(x => x.idUnico === pedId); if(pa && pa.status === 'rascunho') { db.pedidosAtivos = db.pedidosAtivos.filter(x => x.idUnico !== pedId); salvarBanco(); renderizarLista(); let temRascunho = db.pedidosAtivos.some(x => x.status === 'rascunho' && !x.excluido); if(!temRascunho) document.getElementById('containerBotoesEnvio').style.display = 'none'; } } } else { if (getPermissaoColab()) return alert("Seu perfil não permite cancelar ou voltar o status."); const paId = el.getAttribute('data-id'); const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa && !pa.excluido) { if(pa.status === 'entregue') { if(confirm("Deseja voltar este item para 'Pedido ao Fornecedor'?")) { let agora = Date.now(); registrarDesfazer(pa); delete pa.transicaoProgresso; delete pa.statusAnterior; pa.status = 'pedido_forn'; pa.dataStatus = agora; pa.dataPedidoFornecedor = agora; delete pa.dataConclusao; salvarBanco(); renderizarLista(); sincronizarFundo(false, true); } } else if (pa.status === 'pedido_forn' || pa.status === 'comprado') { if(confirm("Deseja voltar este item para 'Pendente'?")) { registrarDesfazer(pa); delete pa.transicaoProgresso; delete pa.statusAnterior; pa.status = 'pendente'; pa.dataStatus = pa.dataEnvio || parseInt(pa.idUnico.split('_')[1]); delete pa.dataConclusao; delete pa.dataPedidoFornecedor; salvarBanco(); renderizarLista(); sincronizarFundo(false, true); } } else if (pa.status === 'pendente') { abrirConfirmarCancelamento(paId); } else if (pa.status === 'cancelado') { registrarDesfazer(pa); delete pa.transicaoProgresso; delete pa.statusAnterior; pa.excluido = true; pa.excluidoCompras = true; pa.status = 'excluido'; pa.dataExclusao = Date.now(); pa.dataStatus = Date.now(); delete pa.dataConclusao; delete pa.dataPedidoFornecedor; salvarBanco(); renderizarLista(); sincronizarFundo(false, true); } } } }

    function deletarPrecoDireto(pId, idx, paId) { if(confirm("Excluir este preço do histórico?")) { let p = db.produtos.find(x => x.id === pId); if(p && p.historicoPrecos) { p.historicoPrecos.splice(idx, 1); salvarBanco(); sincronizarFundo(false, true); if (document.getElementById('modalHistoricoCompra').style.display === 'flex') { abrirHistoricoCompra(paId); } else if(document.getElementById('modalEditarPedido').style.display === 'flex') { abrirModalEditarPedido(paId, pId); } else { abrirFormProduto(pId); } } } }
    function deletarPedidoDireto(idUnico, pId, paId) { if(confirm("Excluir este pedido do histórico geral?")) { let pa = db.pedidosAtivos.find(x => x.idUnico === idUnico); if(pa) { pa.excluido = true; pa.excluidoCompras = true; pa.dataExclusao = Date.now(); salvarBanco(); sincronizarFundo(false, true); if(paId || document.getElementById('modalEditarPedido').style.display === 'flex') abrirModalEditarPedido(paId, pId); else abrirFormProduto(pId); } } }

    function abrirModalEditarPedido(paId, pId) { const p = db.produtos.find(x => x.id === pId); if(!p) return; document.getElementById('tituloModalEditarPedido').innerText = p.nome; let colabLogado = db.colaboradores.find(c => c.id === db.configs.colabAtivoId); let isAdmin = (!colabLogado || colabLogado.isAdmin); let btnEditPed = document.getElementById('btnEditProdPedido'); if(isAdmin) { btnEditPed.style.display = 'block'; btnEditPed.onclick = () => { fecharModal('modalEditarPedido'); abrirFormProduto(p.id, 'modalEditarPedido'); }; } else { btnEditPed.style.display = 'none'; } if (paId) { const pa = db.pedidosAtivos.find(x => x.idUnico === paId); document.getElementById('editPedidoArea').style.display = 'block'; document.getElementById('btnSalvarEdicaoPedido').style.display = 'block'; document.getElementById('editPedidoId').value = paId; document.getElementById('editPedidoQtd').value = pa.qtd; document.getElementById('editPedidoObs').value = pa.obs || ''; const selUn = document.getElementById('editPedidoUnidade'); selUn.innerHTML = ''; p.unidades.forEach(u => selUn.innerHTML += `<option value="${u}" ${pa.unidade===u?'selected':''}>${u}</option>`); } else { document.getElementById('editPedidoArea').style.display = 'none'; document.getElementById('btnSalvarEdicaoPedido').style.display = 'none'; document.getElementById('editPedidoId').value = ''; } let peds = db.pedidosAtivos.filter(x => x.produtoId === pId && x.status !== 'rascunho' && !x.excluido).sort((a,b) => (b.dataEnvio||b.dataStatus||0) - (a.dataEnvio||a.dataStatus||0)); let htmlPedResumo = ""; let htmlPedCompleto = ""; if(peds.length > 0) { let lastP = peds[0]; htmlPedResumo = `<div style="font-size:13px; color:#333;">Último Pedido: ${formatarDataHora(lastP.dataEnvio || lastP.dataStatus)} - <b style="color:#1565C0;">${lastP.qtd} ${lastP.unidade}</b></div>`; peds.slice(0, 15).forEach(paInfo => { htmlPedCompleto += `<div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #eee; padding:5px 0; font-size:12px;"><span>${formatarDataHora(paInfo.dataEnvio || paInfo.dataStatus)} - <b>${paInfo.qtd} ${paInfo.unidade}</b> (${paInfo.status})</span> <button onclick="deletarPedidoDireto('${paInfo.idUnico}', '${pId}', '${paId || ''}')" style="background:none;border:none;color:#d32f2f;cursor:pointer;font-size:16px;">🗑️</button></div>`; }); } else { htmlPedResumo = "<div style='font-size:13px; color:#666;'>Sem histórico de pedidos</div>"; htmlPedCompleto = "<div style='font-size:13px; color:#666;'>Sem histórico de pedidos</div>"; } document.getElementById('resumoHistPedidosEdit').innerHTML = htmlPedResumo; document.getElementById('completoHistPedidosEdit').innerHTML = htmlPedCompleto; document.getElementById('completoHistPedidosEdit').style.display = 'none'; document.getElementById('modalEditarPedido').style.display = 'flex'; }
    function cancelarEdicaoPedido() { const paId = document.getElementById('editPedidoId').value; if(paId) { let pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa && pa.status === 'rascunho') { db.pedidosAtivos = db.pedidosAtivos.filter(x => x.idUnico !== paId); salvarBanco(); renderizarLista(); let temRascunho = db.pedidosAtivos.some(x => x.status === 'rascunho' && !x.excluido); if(!temRascunho) document.getElementById('containerBotoesEnvio').style.display = 'none'; } } fecharModal('modalEditarPedido'); }
    function salvarEdicaoPedido() { const paId = document.getElementById('editPedidoId').value; if(!paId) return fecharModal('modalEditarPedido'); const qtd = parseFloatBr(document.getElementById('editPedidoQtd').value); let pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa) { pa.qtd = qtd; pa.unidade = document.getElementById('editPedidoUnidade').value; pa.obs = document.getElementById('editPedidoObs').value; salvarBanco(); } fecharModal('modalEditarPedido'); renderizarLista(); if(document.getElementById('modalPedidosHoje').style.display === 'flex') { abrirPedidosHoje(); } sincronizarFundo(false, true); }

    function renderizarHistoricoPrecosCompra(pId, paId) { const p = db.produtos.find(prod => prod.id === pId); let revPrecos = (p.historicoPrecos && p.historicoPrecos.length > 0) ? [...p.historicoPrecos].reverse() : []; let htmlPrecosResumo = ""; let htmlPrecosCompleto = ""; if(revPrecos.length > 0) { let undStr = revPrecos[0].unidade ? ` (${revPrecos[0].unidade})` : ''; htmlPrecosResumo = `<div style="font-size:13px; color:#333; margin-bottom: 5px;">Último Preço: ${formatarDataBr(revPrecos[0].data)} - <b style="color:#e65100;">R$ ${revPrecos[0].preco.toLocaleString('pt-BR', {minimumFractionDigits:2})}${undStr}</b>${getNomeFornHTML(revPrecos[0].fornecedorId)}</div>`; revPrecos.forEach((h, i) => { let realIdx = p.historicoPrecos.length - 1 - i; let hUnd = h.unidade ? ` (${h.unidade})` : ''; htmlPrecosCompleto += `<div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #eee; padding:5px 0; font-size:13px;"><div style="line-height:1.2;">${formatarDataBr(h.data)} - <b>R$ ${h.preco.toLocaleString('pt-BR', {minimumFractionDigits:2})}${hUnd}</b>${getNomeFornHTML(h.fornecedorId)}</div> <button onclick="deletarPrecoDireto('${pId}', ${realIdx}, '${paId || ''}')" style="background:none;border:none;color:#d32f2f;cursor:pointer;font-size:16px;">🗑️</button></div>`; }); } else { htmlPrecosResumo = "<div style='font-size:13px; color:#666;'>Nenhum preço registrado.</div>"; htmlPrecosCompleto = "<div style='font-size:13px; color:#666;'>Nenhum preço registrado.</div>"; } document.getElementById('resumoHistPrecosCompra').innerHTML = htmlPrecosResumo; document.getElementById('completoHistPrecosCompra').innerHTML = htmlPrecosCompleto; }
    function adicionarPrecoRapido() { const paId = document.getElementById('histCompraId').value; const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(!pa) return; const p = db.produtos.find(prod => prod.id === pa.produtoId); if(!p) return; const valStr = document.getElementById('novoPrecoCompra').value; const pVal = parseMoeda(valStr); if(pVal <= 0) return alert("Por favor, digite um preço válido."); const fornId = document.getElementById('novoPrecoFornCompra').value; const und = document.getElementById('novoPrecoUndCompra').value; if(!p.historicoPrecos) p.historicoPrecos = []; p.historicoPrecos.push({ data: getHojeSTR(), preco: pVal, unidade: und, fornecedorId: fornId }); if(fornId) { if(!p.fornecedores) p.fornecedores = []; if(!p.fornecedores.includes(fornId)) { p.fornecedores.push(fornId); } } salvarBanco(); sincronizarFundo(false, true); renderizarHistoricoPrecosCompra(p.id, paId); document.getElementById('novoPrecoCompra').value = ''; document.getElementById('novoPrecoFornCompra').value = ''; }

    function abrirHistoricoCompra(paId) { const pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(!pa) return; const pId = pa.produtoId; const p = db.produtos.find(prod => prod.id === pId); if(!p) return; document.getElementById('tituloModalHistoricoCompra').innerText = p.nome; let colabLogado = db.colaboradores.find(c => c.id === db.configs.colabAtivoId); let isAdmin = (!colabLogado || colabLogado.isAdmin); let btnEditComp = document.getElementById('btnEditProdCompra'); if(isAdmin) { btnEditComp.style.display = 'block'; btnEditComp.onclick = () => { fecharModal('modalHistoricoCompra'); abrirFormProduto(p.id, 'modalHistoricoCompra'); }; } else { btnEditComp.style.display = 'none'; } document.getElementById('histCompraId').value = paId; document.getElementById('histCompraQtd').value = pa.qtd; document.getElementById('histCompraObs').value = pa.obs || ''; const selUn = document.getElementById('histCompraUnd'); selUn.innerHTML = ''; p.unidades.forEach(u => selUn.innerHTML += `<option value="${u}" ${pa.unidade===u?'selected':''}>${u}</option>`); let htmlDataConclusao = ""; if((pa.status === 'comprado' || pa.status === 'entregue') && pa.dataConclusao) { htmlDataConclusao = `<p style="color:#1b5e20; font-weight:bold; margin-top:0; font-size:13px;">✅ Marcado como ${pa.status} em: ${formatarDataHora(pa.dataConclusao)}</p>`; } document.getElementById('histCompraDataConclusao').innerHTML = htmlDataConclusao; const selUnPreco = document.getElementById('novoPrecoUndCompra'); selUnPreco.innerHTML = ''; p.unidades.forEach(u => selUnPreco.innerHTML += `<option value="${u}">${u}</option>`); const selForn = document.getElementById('novoPrecoFornCompra'); selForn.innerHTML = '<option value="">(Opcional)</option>'; let fornOrdem = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdem.forEach(f => selForn.innerHTML += `<option value="${f.id}">${f.nome}</option>`); document.getElementById('novoPrecoCompra').value = ''; renderizarHistoricoPrecosCompra(pId, paId); document.getElementById('completoHistPrecosCompra').style.display = 'none'; let comprasPassadas = db.pedidosAtivos.filter(x => x.produtoId === pId && (x.status === 'comprado' || x.status === 'entregue') && x.dataConclusao && x.idUnico !== paId); comprasPassadas.sort((a,b) => b.dataConclusao - a.dataConclusao); let htmlAnaliseResumo = ""; let htmlAnaliseCompleto = ""; if(comprasPassadas.length > 0) { let ultima = comprasPassadas[0]; let qStr = ultima.qtd !== '' ? ultima.qtd : null; let uStr = ultima.unidade ? ultima.unidade : null; let qtdUltima = (qStr !== null && uStr !== null) ? `${qStr} ${uStr}` : (qStr !== null ? `${qStr}` : `${uStr}`); htmlAnaliseResumo += `<div style="font-size:13px; color:#333; margin-bottom:5px;">Última vez: <b>${formatarDataHora(ultima.dataConclusao)}</b> (${qtdUltima})</div>`; if(comprasPassadas.length > 1) { let primeira = comprasPassadas[comprasPassadas.length - 1]; let diffDias = Math.max(1, Math.round((ultima.dataConclusao - primeira.dataConclusao) / (1000 * 60 * 60 * 24))); let frequencia = Math.round(diffDias / (comprasPassadas.length - 1)); if(frequencia > 0) { htmlAnaliseResumo += `<div style="font-size:13px; color:#1565C0;">Freq. Média: <b>a cada ${frequencia} dias</b></div>`; } } else { htmlAnaliseResumo += `<div style="font-size:13px; color:#666;">Apenas 1 compra anterior registrada.</div>`; } comprasPassadas.slice(0, 10).forEach(cp => { let qV = cp.qtd !== '' ? cp.qtd : null; let uV = cp.unidade ? cp.unidade : null; let qF = (qV !== null && uV !== null) ? `${qV} ${uV}` : (qV !== null ? `${qV}` : `${uV}`); let oStr = cp.obs ? `<br><span style="color:#666; font-size:10px;">Obs: ${cp.obs}</span>` : ''; htmlAnaliseCompleto += `<div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #eee; padding:5px 0; font-size:12px;"><span>${formatarDataHora(cp.dataConclusao)} - <b>${qF}</b>${oStr}</span></div>`; }); } else { htmlAnaliseResumo = "<div style='font-size:13px; color:#666;'>Nenhuma compra anterior (concluída) registrada no histórico.</div>"; htmlAnaliseCompleto = "<div style='font-size:13px; color:#666;'>Sem histórico passado.</div>"; } document.getElementById('resumoAnaliseCompras').innerHTML = htmlAnaliseResumo; document.getElementById('completoAnaliseCompras').innerHTML = htmlAnaliseCompleto; document.getElementById('completoAnaliseCompras').style.display = 'none'; let htmlMarcas = ""; if(p && p.marcasAprovadas) { let marcasArr = p.marcasAprovadas.split(',').map(m=>m.trim()).filter(m=>m); if(marcasArr.length > 0) { marcasArr.forEach(m => { let checked = (pa.marcasSelecionadas && pa.marcasSelecionadas.includes(m)) ? 'checked' : ''; htmlMarcas += `<label style="display:inline-block; margin-right:10px; margin-bottom:5px;"><input type="checkbox" value="${m}" onchange="toggleMarcaCompra('${paId}', this.value, this.checked)" ${checked}> ${m}</label>`; }); } else { htmlMarcas = "Nenhuma marca específica cadastrada."; } } else { htmlMarcas = "Nenhuma marca cadastrada no produto."; } document.getElementById('histMarcasLista').innerHTML = htmlMarcas; let htmlEdicao = "<ul style='margin:0; padding-left:20px;'>"; if(pa.historico && pa.historico.length > 0) pa.historico.forEach(h => { htmlEdicao += `<li>${h.data} - ${h.msg}</li>`; }); else htmlEdicao += "<li>Sem edições feitas.</li>"; htmlEdicao += "</ul>"; document.getElementById('histCompraLista').innerHTML = htmlEdicao; document.getElementById('modalHistoricoCompra').style.display = 'flex'; }
    function toggleMarcaCompra(paId, marca, isChecked) { let pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(!pa) return; if(!pa.marcasSelecionadas) pa.marcasSelecionadas = []; if(isChecked) { if(!pa.marcasSelecionadas.includes(marca)) pa.marcasSelecionadas.push(marca); } else { pa.marcasSelecionadas = pa.marcasSelecionadas.filter(m => m !== marca); } salvarBanco(); renderizarLista(); sincronizarFundo(false, true); }
    function salvarDetalhesCompra() { const paId = document.getElementById('histCompraId').value; const qtd = parseFloatBr(document.getElementById('histCompraQtd').value); let pa = db.pedidosAtivos.find(x => x.idUnico === paId); if(pa) { registrarDesfazer(pa); pa.qtd = qtd; pa.unidade = document.getElementById('histCompraUnd').value; pa.obs = document.getElementById('histCompraObs').value; pa.historico = pa.historico || []; pa.historico.push({ data: new Date().toLocaleString(), msg: `Editado em compras: ${qtd} ${pa.unidade}` }); salvarBanco(); } fecharModal('modalHistoricoCompra'); renderizarLista(); sincronizarFundo(false, true); }

    function abrirModalRelatorio() { const selForn = document.getElementById('relatFornecedor'); selForn.innerHTML = '<option value="">-- Todos --</option>'; let fornOrdem = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdem.forEach(f => selForn.innerHTML += `<option value="${f.id}">${f.nome} (Vend: ${f.vendedor || 'N/A'})</option>`); const selColab = document.getElementById('relatColaborador'); selColab.innerHTML = ''; let colabOrdem = [...db.colaboradores].sort((a,b) => a.nome.localeCompare(b.nome)); colabOrdem.forEach(c => selColab.innerHTML += `<option value="${c.id}" ${c.id === db.configs.colabAtivoId ? 'selected' : ''}>${c.nome}</option>`); document.getElementById('modalRelatorio').style.display = 'flex'; gerarTextoRelatorio(); }
    function toggleExclusivoRelatorio(tipo) { if(tipo === 'cotacao' && document.getElementById('relatToggleItens').checked) { document.getElementById('relatTogglePedido').checked = false; } else if (tipo === 'pedido' && document.getElementById('relatTogglePedido').checked) { document.getElementById('relatToggleItens').checked = false; } }
    function gerarTextoRelatorio() { const fornId = document.getElementById('relatFornecedor').value; const res = db.restaurante; const forn = db.fornecedores.find(f => f.id === fornId); const incluirCabecalho = document.getElementById('relatToggleCab').checked; const agruparCat = document.getElementById('relatToggleCat').checked; const isCotacao = document.getElementById('relatToggleItens').checked; const isPedido = document.getElementById('relatTogglePedido').checked; const mostrarQtd = document.getElementById('relatToggleQtd').checked; let blocos = []; if (incluirCabecalho) { let cab = `> *${res.nome.toUpperCase()}*\n> CNPJ: ${res.cnpj}\n> End.: ${res.rua}, ${res.numero}\n> ${res.bairro} - ${res.cidade} / ${res.uf}`; if(res.ponto) cab += `\n> Ponto de referência: ${res.ponto}`; blocos.push(cab); } if (isCotacao) blocos.push(`*ITENS PARA COTAÇÃO:*`); if (isPedido) blocos.push(`*ITENS DO PEDIDO:*`); let itensOrigem = itensSelecionadosRelatorio.size > 0 ? Array.from(itensSelecionadosRelatorio) : Array.from(document.querySelectorAll('.item')).map(el => el.getAttribute('data-id')).filter(id => id && id.includes('_')); let itensProcessados = itensOrigem.map(idUnico => { const pa = db.pedidosAtivos.find(x => x.idUnico === idUnico); const p = pa ? db.produtos.find(x => x.id === pa.produtoId) : null; return { pa, p }; }).filter(item => item.pa && item.p); itensProcessados.sort(ordernarPorCategoriaESub); let blocosItens = []; if (agruparCat) { let gruposArr = []; itensProcessados.forEach(item => { let nomeGrupo = item.p.subcategoria && item.p.subcategoria.trim() !== "" ? item.p.subcategoria.trim() : (db.categorias.find(c => c.id === item.p.categoria)?.nome || "Outros"); let g = gruposArr.find(x => x.nome === nomeGrupo); if(!g) { g = { nome: nomeGrupo, itens: [] }; gruposArr.push(g); } g.itens.push(item); }); gruposArr.forEach(grupo => { let txtCat = `> *${grupo.nome}*\n`; let linhas = grupo.itens.map(item => { let nomeItem = item.p.descFornecedor ? item.p.descFornecedor : item.p.nome; let marcasStr = (item.pa.marcasSelecionadas && item.pa.marcasSelecionadas.length > 0) ? ` - Marca: ${item.pa.marcasSelecionadas.join(', ')}` : ''; let qtyVal = item.pa.qtd !== '' ? item.pa.qtd : null; let unVal = item.pa.unidade ? item.pa.unidade : null; let qtdStr = ""; if (mostrarQtd) { if(qtyVal !== null && unVal !== null) qtdStr = ` *- Qtd: ${qtyVal} ${unVal}*`; else if(qtyVal !== null) qtdStr = ` *- Qtd: ${qtyVal}*`; else if(unVal !== null) qtdStr = ` *- Qtd: ${unVal}*`; } let obsStr = item.pa.obs ? ` *(obs.: ${item.pa.obs})*` : ''; return `▪ ${nomeItem}${marcasStr}${qtdStr}${obsStr}`; }); blocosItens.push(txtCat + linhas.join('\n')); }); } else { let linhas = itensProcessados.map(item => { let nomeItem = item.p.descFornecedor ? item.p.descFornecedor : item.p.nome; let marcasStr = (item.pa.marcasSelecionadas && item.pa.marcasSelecionadas.length > 0) ? ` - Marca: ${item.pa.marcasSelecionadas.join(', ')}` : ''; let qtyVal = item.pa.qtd !== '' ? item.pa.qtd : null; let unVal = item.pa.unidade ? item.pa.unidade : null; let qtdStr = ""; if (mostrarQtd) { if(qtyVal !== null && unVal !== null) qtdStr = ` *- Qtd: ${qtyVal} ${unVal}*`; else if(qtyVal !== null) qtdStr = ` *- Qtd: ${qtyVal}*`; else if(unVal !== null) qtdStr = ` *- Qtd: ${unVal}*`; } let obsStr = item.pa.obs ? ` *(obs.: ${item.pa.obs})*` : ''; return `▪ ${nomeItem}${marcasStr}${qtdStr}${obsStr}`; }); if(linhas.length > 0) blocosItens.push(linhas.join('\n')); } if (blocosItens.length > 0) blocos.push(blocosItens.join('\n\n')); document.getElementById('relatTexto').value = blocos.join('\n\n'); const btnZap = document.querySelector('.btn-whatsapp'); if(forn && forn.telefone) { btnZap.dataset.tel = forn.telefone; } else { btnZap.dataset.tel = ""; } }
    function enviarWhatsAppAPI() { const texto = document.getElementById('relatTexto').value; const fornId = document.getElementById('relatFornecedor').value; const forn = db.fornecedores.find(f => f.id === fornId); const tel = forn ? forn.telefone : null; if(tel) { let num = tel.replace(/\D/g,''); if(num.length === 10 || num.length === 11) num = '55' + num; window.open(`https://wa.me/${num}?text=${encodeURIComponent(texto)}`, '_blank'); } else { const txtArea = document.getElementById('relatTexto'); txtArea.select(); document.execCommand('copy'); alert("Copiado! Selecione o contato no WhatsApp manualmente."); window.open(`https://wa.me/`, '_blank'); } }

    function abrirAdmin() { document.getElementById('inputSenhaAdmin').value = ''; document.getElementById('modalSenhaAdmin').style.display = 'flex'; setTimeout(() => document.getElementById('inputSenhaAdmin').focus(), 100); }
    
    function abrirGerenciar(tipo, preserveState = false) { fecharModal('modalPainelUnificado'); const lista = document.getElementById('conteudoListagem'); const btnNovo = document.getElementById('btnNovoListagem'); const titulo = document.getElementById('tituloListagem'); const boxFiltro = document.getElementById('filtroGerenciarCatBox'); const barAlfabeto = document.getElementById('sidebarAlfabeto'); let htmlLista = ''; if(!preserveState) { currentGerenciarFiltro = 'todos'; currentGerenciarBusca = ''; } if(tipo === 'restaurante') { fecharModal('modalListagem'); document.getElementById('restNome').value = db.restaurante.nome; document.getElementById('restCNPJ').value = db.restaurante.cnpj; document.getElementById('restRua').value = db.restaurante.rua; document.getElementById('restNum').value = db.restaurante.numero; document.getElementById('restBairro').value = db.restaurante.bairro; document.getElementById('restCidade').value = db.restaurante.cidade; document.getElementById('restUF').value = db.restaurante.uf || 'PB'; document.getElementById('restPonto').value = db.restaurante.ponto; document.getElementById('modalFormRestaurante').style.display = 'flex'; return; } if(tipo === 'produtos') { titulo.innerText = "Produtos"; btnNovo.onclick = () => abrirFormProduto(null); const selFiltro = document.getElementById('filtroGerenciarCat'); selFiltro.innerHTML = '<option value="todos">-- Todas as Categorias --</option>'; db.categorias.forEach(c => selFiltro.innerHTML += `<option value="${c.id}">${c.nome}</option>`); boxFiltro.style.display = 'flex'; document.getElementById('filtroGerenciarCat').value = currentGerenciarFiltro; document.getElementById('inputBuscaProd').value = currentGerenciarBusca; barAlfabeto.style.display = 'flex'; barAlfabeto.innerHTML = ''; "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('').forEach(l => { barAlfabeto.innerHTML += `<div onclick="rolarParaLetra('${l}')">${l}</div>`; }); renderizarFiltroGerenciar(); } else { boxFiltro.style.display = 'none'; barAlfabeto.style.display = 'none'; if (tipo === 'categorias') { titulo.innerText = "Categorias"; btnNovo.onclick = () => abrirFormCategoria(null); db.categorias.forEach((c, index) => { htmlLista += `<div class="gerenciar-item" style="border-bottom: 1px solid #ddd; padding-bottom: 10px; margin-bottom: 5px;"><div style="display: flex; justify-content: space-between; align-items: center; width: 100%;"><div class="gerenciar-info"><span class="color-preview" style="background:${c.cor}; color:${c.corTexto}; padding:4px 8px; border-radius:4px; font-weight: bold; font-size: 14px;">${c.nome}</span></div><div class="gerenciar-actions"><button onclick="moverCategoria(${index}, -1)">⬆️</button><button onclick="moverCategoria(${index}, 1)">⬇️</button><button onclick="abrirFormCategoria('${c.id}')">✏️</button><button onclick="excluirItem('categorias', '${c.id}')">🗑️</button></div></div></div>`; }); } else if (tipo === 'colaboradores') { titulo.innerText = "Colaboradores"; btnNovo.onclick = () => abrirFormColaborador(null); let colabOrdem = [...db.colaboradores].sort((a,b) => a.nome.localeCompare(b.nome)); colabOrdem.forEach((c) => { htmlLista += `<div class="gerenciar-item"><div class="gerenciar-info"><strong>${c.nome}</strong></div><div class="gerenciar-actions"><button onclick="abrirFormColaborador('${c.id}')">✏️</button><button onclick="excluirItem('colaboradores', '${c.id}')">🗑️</button></div></div>`; }); } else if (tipo === 'fornecedores') { titulo.innerText = "Fornecedores"; btnNovo.onclick = () => abrirFormFornecedor(null); let fornOrdem = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdem.forEach((f) => { htmlLista += `<div class="gerenciar-item"><div class="gerenciar-info"><strong>${f.nome}</strong><br><span style="color:#666">${f.telefone}</span></div><div class="gerenciar-actions"><button onclick="abrirFormFornecedor('${f.id}')">✏️</button><button onclick="excluirItem('fornecedores', '${f.id}')">🗑️</button></div></div>`; }); } lista.innerHTML = htmlLista; } document.getElementById('modalListagem').style.display = 'flex'; }
    function renderizarFiltroGerenciar() { const lista = document.getElementById('conteudoListagem'); currentGerenciarFiltro = document.getElementById('filtroGerenciarCat').value; currentGerenciarBusca = document.getElementById('inputBuscaProd').value.toLowerCase().trim(); const filtro = currentGerenciarFiltro; const busca = currentGerenciarBusca; let htmlLista = ''; let prodOrdem = [...db.produtos].sort((a,b) => a.nome.localeCompare(b.nome)); prodOrdem.forEach((p) => { if (p.avulso) return; if (filtro !== 'todos' && p.categoria !== filtro) return; if (busca && !p.nome.toLowerCase().includes(busca)) return; let letraInicial = removerAcentos(p.nome).charAt(0).toUpperCase(); let nSubcat = p.subcategoria ? ` <span style="font-size:10px; color:#888;">(${p.subcategoria})</span>` : ''; htmlLista += `<div class="gerenciar-item" data-letra="${letraInicial}"><div class="gerenciar-info"><strong>${p.nome}</strong><br><span style="color:#666">${db.categorias.find(c=>c.id===p.categoria)?.nome || ''}</span>${nSubcat}</div><div class="gerenciar-actions"><button onclick="abrirFormProduto('${p.id}')">✏️</button><button onclick="duplicarProduto('${p.id}')" title="Duplicar">📑</button><button onclick="excluirItem('produtos', '${p.id}')">🗑️</button></div></div>`; }); lista.innerHTML = htmlLista; }
    function rolarParaLetra(letraClicada) { const alfabeto = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"; let indexInicial = alfabeto.indexOf(letraClicada); let containerLista = document.getElementById('conteudoListagem'); let elementoAlvo = null; for (let i = indexInicial; i < alfabeto.length; i++) { elementoAlvo = document.querySelector(`.gerenciar-item[data-letra="${alfabeto[i]}"]`); if (elementoAlvo) break; } if(elementoAlvo) { containerLista.scrollTo({ top: elementoAlvo.offsetTop - containerLista.offsetTop, behavior: 'smooth' }); } }
    function moverCategoria(index, direcao) { if (direcao === -1 && index > 0) { let temp = db.categorias[index]; db.categorias[index] = db.categorias[index - 1]; db.categorias[index - 1] = temp; } else if (direcao === 1 && index < db.categorias.length - 1) { let temp = db.categorias[index]; db.categorias[index] = db.categorias[index + 1]; db.categorias[index + 1] = temp; } marcarMudancaEstrutural(); abrirGerenciar('categorias', true); sincronizarFundo(false, true); }
    function excluirItem(tipo, id) { if(confirm("Tem certeza?")) { db[tipo] = db[tipo].filter(x => x.id !== id); marcarMudancaEstrutural(); abrirGerenciar(tipo, true); renderizarLista(); sincronizarFundo(false, true); } }
    function duplicarProduto(id) { if(confirm("Deseja duplicar este produto com os exatos mesmos dados e nome?")) { let p = db.produtos.find(x => x.id === id); if(!p) return; let copia = JSON.parse(JSON.stringify(p)); copia.id = 'p_' + Date.now(); db.produtos.push(copia); marcarMudancaEstrutural(); abrirGerenciar('produtos', true); sincronizarFundo(false, true); } }
    function salvarRestaurante() { db.restaurante.nome = document.getElementById('restNome').value; db.restaurante.cnpj = document.getElementById('restCNPJ').value; db.restaurante.rua = document.getElementById('restRua').value; db.restaurante.numero = document.getElementById('restNum').value; db.restaurante.bairro = document.getElementById('restBairro').value; db.restaurante.cidade = document.getElementById('restCidade').value; db.restaurante.uf = document.getElementById('restUF').value; db.restaurante.ponto = document.getElementById('restPonto').value; marcarMudancaEstrutural(); fecharModal('modalFormRestaurante'); document.getElementById('modalPainelUnificado').style.display = 'flex'; sincronizarFundo(false, true); }
    
    function renderizarFornecedoresVinculados() { const box = document.getElementById('listaFornecedoresVinculados'); box.innerHTML = ''; if(tempFornecedoresProduto.length === 0) { box.innerHTML = '<span style="font-size:12px; color:#999;">Nenhum fornecedor vinculado.</span>'; return; } tempFornecedoresProduto.forEach(fId => { let f = db.fornecedores.find(x => x.id === fId); if(f) { box.innerHTML += `<div style="display:flex; justify-content:space-between; align-items:center; background:#e3f2fd; padding:6px 10px; border-radius:4px; font-size:13px; color:#1565C0; font-weight:bold;"><span>${f.nome}</span><button onclick="removerFornecedorVinculado('${f.id}')" style="background:none; border:none; cursor:pointer; color:#d32f2f; font-size:16px;">×</button></div>`; } }); }
    function removerFornecedorVinculado(id) { tempFornecedoresProduto = tempFornecedoresProduto.filter(x => x !== id); renderizarFornecedoresVinculados(); }
    function abrirModalSelecaoFornecedores() { const box = document.getElementById('boxListaFornecedoresSelecao'); box.innerHTML = ''; if(db.fornecedores.length === 0) { box.innerHTML = '<span style="font-size:13px; color:#666; padding:10px; display:block;">Nenhum fornecedor cadastrado no sistema.</span>'; } else { let fornOrdem = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdem.forEach(f => { let checked = tempFornecedoresProduto.includes(f.id) ? 'checked' : ''; box.innerHTML += `<label style="display:flex; align-items:center; padding:10px; border-bottom:1px solid #eee; font-size:14px; cursor:pointer;"><input type="checkbox" value="${f.id}" class="chk-selecao-forn" style="margin-right:10px; width:18px; height:18px;" ${checked}>${f.nome}</label>`; }); } document.getElementById('modalSelecaoFornecedores').style.display = 'flex'; }
    function confirmarSelecaoFornecedores() { tempFornecedoresProduto = Array.from(document.querySelectorAll('.chk-selecao-forn:checked')).map(el => el.value); fecharModal('modalSelecaoFornecedores'); renderizarFornecedoresVinculados(); }
    function atualizarComboSubcat(selecionada = '') { const catId = document.getElementById('prodCategoria').value; const cat = db.categorias.find(c => c.id === catId); const combo = document.getElementById('prodSubcategoria'); combo.innerHTML = '<option value="">-- Nenhuma --</option>'; if(cat && cat.subcategorias) { cat.subcategorias.forEach(s => combo.innerHTML += `<option value="${s}" ${selecionada===s?'selected':''}>${s}</option>`); } }

    function cancelarFormProduto() { const origem = origemFormProduto; const pId = document.getElementById('prodId').value; origemFormProduto = null; fecharModal('modalFormProduto'); if(origem === 'modalEditarPedido') { abrirModalEditarPedido(document.getElementById('editPedidoId').value || null, pId); } else if(origem === 'modalHistoricoCompra') { const paId = document.getElementById('histCompraId').value; if(paId) abrirHistoricoCompra(paId); else abrirGerenciar('produtos', true); } else { abrirGerenciar('produtos', true); } }

    function abrirFormProduto(id, origem = null) { origemFormProduto = origem; fecharModal('modalListagem'); const combo = document.getElementById('prodCategoria'); combo.innerHTML = ''; db.categorias.forEach(c => combo.innerHTML += `<option value="${c.id}">${c.nome}</option>`); document.getElementById('prodPreco').value = ''; document.getElementById('prodPrecoData').value = getHojeSTR(); const selFornForm = document.getElementById('prodPrecoForn'); selFornForm.innerHTML = '<option value="">(Opcional)</option>'; let fornOrdemForm = [...db.fornecedores].sort((a,b) => a.nome.localeCompare(b.nome)); fornOrdemForm.forEach(f => selFornForm.innerHTML += `<option value="${f.id}">${f.nome}</option>`); let p = null; if(id) { p = db.produtos.find(x => x.id === id); document.getElementById('prodId').value = id; document.getElementById('prodNome').value = p.nome; document.getElementById('prodDesc').value = p.descFornecedor || ''; document.getElementById('prodObsPadrao').value = p.obsPadrao || ''; document.getElementById('prodCategoria').value = p.categoria; document.getElementById('prodUnidades').value = p.unidades.join(', '); document.getElementById('prodMarcasOk').value = p.marcasAprovadas; document.getElementById('prodMarcasNok').value = p.marcasReprovadas; document.getElementById('prodQtdPadrao').value = (p.qtdPadrao !== null && p.qtdPadrao !== '') ? p.qtdPadrao : ''; tempPrecosProduto = p.historicoPrecos ? JSON.parse(JSON.stringify(p.historicoPrecos)) : []; tempFornecedoresProduto = p.fornecedores ? JSON.parse(JSON.stringify(p.fornecedores)) : []; atualizarComboSubcat(p.subcategoria); document.getElementById('boxHistoricoPrecos').style.display = 'block'; document.getElementById('boxHistoricoPedidosProdutoForm').style.display = 'block'; } else { document.getElementById('prodId').value = ''; document.getElementById('prodNome').value = ''; document.getElementById('prodDesc').value = ''; document.getElementById('prodObsPadrao').value = ''; document.getElementById('prodUnidades').value = ''; document.getElementById('prodMarcasOk').value = ''; document.getElementById('prodMarcasNok').value = ''; document.getElementById('prodQtdPadrao').value = ''; tempPrecosProduto = []; tempFornecedoresProduto = []; atualizarComboSubcat(); document.getElementById('boxHistoricoPrecos').style.display = 'none'; document.getElementById('boxHistoricoPedidosProdutoForm').style.display = 'none'; } let htmlPrecosResumoForm = ""; let htmlPrecosCompletoForm = ""; if(tempPrecosProduto.length > 0) { let revPrecos = [...tempPrecosProduto].reverse(); let undStr = revPrecos[0].unidade ? ` (${revPrecos[0].unidade})` : ''; htmlPrecosResumoForm = `<div style="font-size:13px; color:#333;">Último Preço: ${formatarDataBr(revPrecos[0].data)} - <b style="color:#e65100;">R$ ${revPrecos[0].preco.toLocaleString('pt-BR', {minimumFractionDigits:2})}${undStr}</b>${getNomeFornHTML(revPrecos[0].fornecedorId)}</div>`; revPrecos.forEach((h, i) => { let realIdx = tempPrecosProduto.length - 1 - i; let hUnd = h.unidade ? ` (${h.unidade})` : ''; htmlPrecosCompletoForm += `<div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #eee; padding:5px 0; font-size:13px;"><div style="line-height:1.2;">${formatarDataBr(h.data)} - <b>R$ ${h.preco.toLocaleString('pt-BR', {minimumFractionDigits:2})}${hUnd}</b>${getNomeFornHTML(h.fornecedorId)}</div> <button onclick="deletarPrecoDireto('${id}', ${realIdx}, null)" style="background:none;border:none;color:#d32f2f;cursor:pointer;font-size:16px;">🗑️</button></div>`; }); } else { htmlPrecosResumoForm = "<div style='font-size:13px; color:#666;'>Sem histórico</div>"; htmlPrecosCompletoForm = "<div style='font-size:13px; color:#666;'>Sem histórico</div>"; document.getElementById('boxHistoricoPrecos').style.display = 'none'; } let htmlPedResumoForm = ""; let htmlPedCompletoForm = ""; let peds = db.pedidosAtivos.filter(x => x.produtoId === id && x.status !== 'rascunho' && !x.excluido).sort((a,b) => (b.dataEnvio||b.dataStatus||0) - (a.dataEnvio||a.dataStatus||0)); if(peds.length > 0) { let lastP = peds[0]; htmlPedResumoForm = `<div style="font-size:13px; color:#333;">Último Pedido: ${formatarDataHora(lastP.dataEnvio || lastP.dataStatus)} - <b style="color:#1565C0;">${lastP.qtd} ${lastP.unidade}</b></div>`; peds.slice(0, 15).forEach(paInfo => { htmlPedCompletoForm += `<div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #eee; padding:5px 0; font-size:12px;"><span>${formatarDataHora(paInfo.dataEnvio || paInfo.dataStatus)} - <b>${paInfo.qtd} ${paInfo.unidade}</b> (${paInfo.status})</span> <button onclick="deletarPedidoDireto('${paInfo.idUnico}', '${id}', null)" style="background:none;border:none;color:#d32f2f;cursor:pointer;font-size:16px;">🗑️</button></div>`; }); } else { htmlPedResumoForm = "<div style='font-size:13px; color:#666;'>Sem histórico</div>"; htmlPedCompletoForm = "<div style='font-size:13px; color:#666;'>Sem histórico</div>"; document.getElementById('boxHistoricoPedidosProdutoForm').style.display = 'none'; } document.getElementById('resumoPrecosProduto').innerHTML = htmlPrecosResumoForm; document.getElementById('listaPrecosProduto').innerHTML = htmlPrecosCompletoForm; document.getElementById('listaPrecosProduto').style.display = 'none'; document.getElementById('resumoPedidosProdutoForm').innerHTML = htmlPedResumoForm; document.getElementById('listaHistoricoPedidosProdutoForm').innerHTML = htmlPedCompletoForm; document.getElementById('listaHistoricoPedidosProdutoForm').style.display = 'none'; renderizarFornecedoresVinculados(); document.getElementById('modalFormProduto').style.display = 'flex'; }
    
    function salvarProduto() { origemFormProduto = null; const id = document.getElementById('prodId').value || 'p_'+Date.now(); const unArr = document.getElementById('prodUnidades').value.toLowerCase().split(',').map(u=>u.trim()).filter(u=>u); const pVal = parseMoeda(document.getElementById('prodPreco').value); const pData = document.getElementById('prodPrecoData').value; let qtdStr = document.getElementById('prodQtdPadrao').value.trim(); const qtdPadrao = qtdStr !== '' ? parseFloatBr(qtdStr) : ''; const fornIdPreco = document.getElementById('prodPrecoForn').value; if(pVal > 0) { tempPrecosProduto.push({ data: pData, preco: pVal, fornecedorId: fornIdPreco }); if(fornIdPreco && !tempFornecedoresProduto.includes(fornIdPreco)) { tempFornecedoresProduto.push(fornIdPreco); } } const novo = { id: id, nome: document.getElementById('prodNome').value, descFornecedor: document.getElementById('prodDesc').value, obsPadrao: document.getElementById('prodObsPadrao').value, categoria: document.getElementById('prodCategoria').value, subcategoria: document.getElementById('prodSubcategoria').value, qtdPadrao: qtdPadrao, unidades: unArr.length>0 ? unArr : [''], marcasAprovadas: document.getElementById('prodMarcasOk').value, marcasReprovadas: document.getElementById('prodMarcasNok').value, historicoPrecos: tempPrecosProduto, fornecedores: tempFornecedoresProduto }; const idx = db.produtos.findIndex(x => x.id === id); if(idx >= 0) db.produtos[idx] = novo; else db.produtos.push(novo); marcarMudancaEstrutural(); fecharModal('modalFormProduto'); abrirGerenciar('produtos', true); renderizarLista(); sincronizarFundo(false, true); }

    function renderFormSubcats() { const list = document.getElementById('listaSubcatsForm'); let htmlLista = ''; tempSubcats.forEach((s, i) => { htmlLista += `<div style="display:flex; justify-content:space-between; align-items:center; background:#f0f0f0; padding:6px 10px; border-radius:4px; margin-bottom:4px;"><span style="font-size:13px; font-weight:bold; color:#333;">${s}</span><div style="display:flex; gap:2px;"><button onclick="moverFormSubcat(${i}, -1)" style="border:none;background:#e0e0e0;border-radius:3px;cursor:pointer;font-size:12px;padding:4px 6px;">⬆️</button><button onclick="moverFormSubcat(${i}, 1)" style="border:none;background:#e0e0e0;border-radius:3px;cursor:pointer;font-size:12px;padding:4px 6px;">⬇️</button><button onclick="editarFormSubcat(${i})" style="border:none;background:#e0e0e0;border-radius:3px;cursor:pointer;font-size:12px;padding:4px 6px;">✏️</button><button onclick="removerFormSubcat(${i})" style="border:none;background:#ffcdd2;color:#d32f2f;border-radius:3px;cursor:pointer;font-weight:bold;font-size:12px;padding:4px 6px;">✕</button></div></div>`; }); list.innerHTML = htmlLista; }
    function addFormSubcat() { let val = document.getElementById('novaSubcatNome').value.trim(); if(val) { tempSubcats.push(val); renderFormSubcats(); document.getElementById('novaSubcatNome').value = ''; } }
    function moverFormSubcat(idx, dir) { if(dir === -1 && idx > 0) { let t = tempSubcats[idx]; tempSubcats[idx] = tempSubcats[idx-1]; tempSubcats[idx-1] = t; } if(dir === 1 && idx < tempSubcats.length-1) { let t = tempSubcats[idx]; tempSubcats[idx] = tempSubcats[idx+1]; tempSubcats[idx+1] = t; } renderFormSubcats(); }
    function editarFormSubcat(idx) { let n = prompt("Novo nome para a subcategoria:", tempSubcats[idx]); if(n && n.trim() !== "") { tempRenames.push({old: tempSubcats[idx], new: n.trim()}); tempSubcats[idx] = n.trim(); renderFormSubcats(); } }
    function removerFormSubcat(idx) { tempSubcats.splice(idx, 1); renderFormSubcats(); }

    function abrirFormCategoria(id) { fecharModal('modalListagem'); document.getElementById('novaSubcatNome').value = ''; tempRenames = []; const chkAvulso = document.getElementById('catPermiteAvulso'); if(id) { const c = db.categorias.find(x => x.id === id); document.getElementById('catId').value = id; document.getElementById('catNome').value = c.nome; document.getElementById('catCor').value = c.cor; document.getElementById('catCorTexto').value = c.corTexto; tempSubcats = c.subcategorias ? [...c.subcategorias] : []; chkAvulso.checked = c.permiteAvulso || false; chkAvulso.disabled = true; } else { document.getElementById('catId').value = ''; document.getElementById('catNome').value = ''; document.getElementById('catCor').value = '#1565C0'; document.getElementById('catCorTexto').value = '#ffffff'; tempSubcats = []; chkAvulso.checked = false; chkAvulso.disabled = false; } renderFormSubcats(); document.getElementById('modalFormCategoria').style.display = 'flex'; }
    function salvarCategoria() { const id = document.getElementById('catId').value || 'c_'+Date.now(); if(tempRenames.length > 0) { db.produtos.forEach(p => { if(p.categoria === id) { let rename = tempRenames.find(r => r.old === p.subcategoria); if(rename) p.subcategoria = rename.new; } }); } const novo = { id: id, nome: document.getElementById('catNome').value, cor: document.getElementById('catCor').value, corTexto: document.getElementById('catCorTexto').value, subcategorias: tempSubcats, permiteAvulso: document.getElementById('catPermiteAvulso').checked }; const idx = db.categorias.findIndex(x => x.id === id); if(idx >= 0) { novo.permiteAvulso = db.categorias[idx].permiteAvulso || false; db.categorias[idx] = novo; } else { db.categorias.push(novo); } marcarMudancaEstrutural(); fecharModal('modalFormCategoria'); abrirGerenciar('categorias', true); renderizarLista(); sincronizarFundo(false, true); }

    function abrirFormColaborador(id) { fecharModal('modalListagem'); const box = document.getElementById('colabCategoriasBox'); box.innerHTML = ''; const c = id ? db.colaboradores.find(x => x.id === id) : null; document.getElementById('colabIsAdmin').checked = c ? (c.isAdmin || false) : false; document.getElementById('colabApenasReceber').checked = c ? (c.apenasReceber || false) : false; db.categorias.forEach(cat => { let checkPed = (!c || (c.catsPermitidasPedido !== undefined ? c.catsPermitidasPedido.includes(cat.id) : (c.catsPermitidas ? c.catsPermitidas.includes(cat.id) : true))) ? 'checked' : ''; let checkComp = (!c || (c.catsPermitidasCompras !== undefined ? c.catsPermitidasCompras.includes(cat.id) : (c.catsPermitidas ? c.catsPermitidas.includes(cat.id) : true))) ? 'checked' : ''; box.innerHTML += `<div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; border-bottom:1px solid #ddd; padding-bottom:6px;"><span style="font-weight:bold; font-size:12px; flex:1; color:#333;">${cat.nome}</span><div style="display:flex; gap:15px;"><label style="display:flex; flex-direction:column; align-items:center; font-size:9px; color:#555; gap:2px;"><div class="switch" style="margin:0;"><input type="checkbox" value="${cat.id}" class="chk-cat-pedido" ${checkPed}><span class="slider"></span></div>Pedidos</label><label style="display:flex; flex-direction:column; align-items:center; font-size:9px; color:#555; gap:2px;"><div class="switch" style="margin:0;"><input type="checkbox" value="${cat.id}" class="chk-cat-compras" ${checkComp}><span class="slider"></span></div>Compras</label></div></div>`; }); document.getElementById('colabId').value = id || ''; document.getElementById('colabNome').value = c ? c.nome : ''; document.getElementById('colabSenha').value = c ? c.senha : ''; document.getElementById('modalFormColaborador').style.display = 'flex'; }
    
    function salvarColaborador() { 
        const id = document.getElementById('colabId').value || 'col_'+Date.now(); 
        const isAdmin = document.getElementById('colabIsAdmin').checked; 
        
        if (!isAdmin) {
            let outrosAdmins = db.colaboradores.filter(c => c.isAdmin && c.id !== id);
            if (outrosAdmins.length === 0 && db.colaboradores.length > 0) {
                return alert("⚠️ Não é possível remover o único administrador do sistema.");
            }
        }

        const catsPed = Array.from(document.querySelectorAll('.chk-cat-pedido:checked')).map(el => el.value); const catsComp = Array.from(document.querySelectorAll('.chk-cat-compras:checked')).map(el => el.value); const s = document.getElementById('colabSenha').value; const apenasReceber = document.getElementById('colabApenasReceber').checked; const novo = { id: id, nome: document.getElementById('colabNome').value, telefone: "", senha: s, isAdmin: isAdmin, apenasReceber: apenasReceber, catsPermitidasPedido: catsPed, catsPermitidasCompras: catsComp, catsPermitidas: [] }; const idx = db.colaboradores.findIndex(x => x.id === id); if(idx >= 0) db.colaboradores[idx] = novo; else db.colaboradores.push(novo); marcarMudancaEstrutural(); fecharModal('modalFormColaborador'); abrirGerenciar('colaboradores', true); sincronizarFundo(false, true); 
    }

    function abrirFormFornecedor(id) { fecharModal('modalListagem'); if(id) { const f = db.fornecedores.find(x => x.id === id); document.getElementById('fornId').value = id; document.getElementById('fornNome').value = f.nome; document.getElementById('fornVendedor').value = f.vendedor || ''; document.getElementById('fornTel').value = f.telefone || ''; document.getElementById('fornNomeGerente').value = f.nomeGerente || ''; document.getElementById('fornTelGerente').value = f.telGerente || ''; document.getElementById('fornTelEmpresa').value = f.telEmpresa || ''; } else { document.getElementById('fornId').value = ''; document.getElementById('fornNome').value = ''; document.getElementById('fornVendedor').value = ''; document.getElementById('fornTel').value = ''; document.getElementById('fornNomeGerente').value = ''; document.getElementById('fornTelGerente').value = ''; document.getElementById('fornTelEmpresa').value = ''; } document.getElementById('modalFormFornecedor').style.display = 'flex'; }
    function salvarFornecedor() { const id = document.getElementById('fornId').value || 'f_'+Date.now(); const novo = { id: id, nome: document.getElementById('fornNome').value, vendedor: document.getElementById('fornVendedor').value, telefone: document.getElementById('fornTel').value, nomeGerente: document.getElementById('fornNomeGerente').value, telGerente: document.getElementById('fornTelGerente').value, telEmpresa: document.getElementById('fornTelEmpresa').value }; const idx = db.fornecedores.findIndex(x => x.id === id); if(idx >= 0) db.fornecedores[idx] = novo; else db.fornecedores.push(novo); marcarMudancaEstrutural(); fecharModal('modalFormFornecedor'); abrirGerenciar('fornecedores', true); sincronizarFundo(false, true); }
